#!/usr/bin/env bash
# =============================================================================
# COMP2812 / COMP9812 Systems Software — Distro Minimisation Project
# starter.sh: build your starting system, then record its baseline (online version)
#
# Run it on a NEW Ubuntu Server 26.04 VM — never on your lab VM.
# Run it TWICE, from your own account, with sudo:
#
#   1st run:  sudo bash starter.sh
#             Installs the desktop and the "inherited workstation".
#             Then restart, log in, and wait for Firefox to open the page.
#   2nd run:  sudo bash starter.sh
#             Asks for your FAN and subsystem, records the
#             baseline and prints
#             your BASELINE ID. Put it in your write-up.
#
# Safe to run again if the 1st run stops part-way.
# =============================================================================

set -uo pipefail
SCRIPT_VERSION="2027.6-online"
LOG=/var/log/minproj-starter.log
STATE=/var/lib/minproj

# Messages go to the screen and to the log file.
say()  { printf -- "$@"; printf -- "$@" >> "$LOG" 2>/dev/null; }
step() { say '\n==> %s\n' "$*"; }
ok()   { say '    ok    %s\n' "$*"; }
warn() { say '    WARN  %s\n' "$*"; WARNINGS=$((WARNINGS+1)); }
fail() { say '\nSTOPPED: %s\n' "$*"; exit 1; }
# Runs a long command with no keyboard input and its output in the log,
# and prints a line every minute so you can see it is still working.
long() {
  "$@" < /dev/null >> "$LOG" 2>&1 &
  local pid=$! secs=0
  while kill -0 "$pid" 2>/dev/null; do
    sleep 5; secs=$((secs+5))
    [ $((secs % 60)) -eq 0 ] && say '    ...   still working (%d min) - this is normal\n' $((secs/60))
  done
  wait "$pid"
}
WARNINGS=0
TEST=0; [ "${1:-}" = "--staff-test" ] && TEST=1   # staff only: skips snaps, kernel and services

# ---- 0. checks before changing anything ---------------------------------------
[ "$(id -u)" -eq 0 ] || fail "run it with sudo:   sudo bash $0"
U="${SUDO_USER:-}"
[ -n "$U" ] && [ "$U" != "root" ] || fail "run it from your own account with sudo, not from a root shell."
UHOME=$(getent passwd "$U" | cut -d: -f6)
. /etc/os-release
[ "${ID:-}" = "ubuntu" ] || fail "this is ${PRETTY_NAME:-not Ubuntu}. Use a new Ubuntu Server 26.04 VM."
ARCH=$(uname -m)
case "$ARCH" in x86_64|aarch64) ;; *) fail "unsupported CPU architecture: $ARCH" ;; esac
if [ -d /opt/systems-software ] || [ "$(hostname)" = "systems-software" ]; then
  fail "this is your LAB VM. Make a NEW VM for the project (see the Student Spec, section 4). Your lab VM stays as it is."
fi
HAVE_SYSTEMD=0; [ -d /run/systemd/system ] && HAVE_SYSTEMD=1
mkdir -p "$STATE"

# ---- 2nd run: record the baseline ----------------------------------------------
if [ -f "$STATE/STAGE" ] && [ "$(cat "$STATE/STAGE")" = installed ]; then
  echo "Recording the baseline."
  echo "Before you go on: Firefox must be open and showing the page with the"
  echo "green 'JS: PASSED' badge."
  if [ -f "$STATE/baseline.txt" ]; then
    /usr/local/bin/final-check --record-baseline 0; exit 0
  fi
  TEAM=""
  while ! [[ "$TEAM" =~ ^[a-z]{2,4}[0-9]{4}$ ]]; do
    read -r -p "Your FAN (for example stud0123): " TEAM
    TEAM=$(printf '%s' "$TEAM" | tr 'A-Z' 'a-z' | tr -d ' ')
  done
  echo "Your subsystem (you cannot change it later):"
  echo "  1  Boot and startup"
  echo "  2  Packages and dependencies"
  echo "  3  Display and session"
  echo "  4  Services and security"
  SUB=""
  while [ -z "$SUB" ]; do
    read -r -p "Type 1, 2, 3 or 4: " n
    case "$n" in 1) SUB=boot; SN="Boot and startup" ;; 2) SUB=packages; SN="Packages and dependencies" ;;
                 3) SUB=display; SN="Display and session" ;; 4) SUB=services; SN="Services and security" ;; esac
  done
  read -r -p "FAN $TEAM, $SN - is that correct? (y/n) " yn
  [ "$yn" = y ] || fail "run the script again and type your FAN and subsystem."
  /usr/local/bin/final-check --record-baseline "$TEAM" "$SUB"
  exit $?
fi

say "---- starter.sh $SCRIPT_VERSION  $(date -Is)  user=$U  $PRETTY_NAME  $ARCH\n"
[ "${VERSION_ID:-}" = "26.04" ] || warn "made for Ubuntu 26.04 - this is ${VERSION_ID:-unknown}. Continuing."

# ---- 1. use the whole virtual disk -------------------------------------------
step "Checking the disk size"
ROOT_DEV=$(findmnt -no SOURCE / 2>/dev/null)
if command -v lvs >/dev/null && lvs "$ROOT_DEV" >/dev/null 2>&1; then
  VG=$(lvs --noheadings -o vg_name "$ROOT_DEV" | tr -d ' ')
  VG_FREE_MB=$(vgs --noheadings --units m --nosuffix -o vg_free "$VG" | tr -d ' ' | cut -d. -f1)
  if [ "${VG_FREE_MB:-0}" -gt 1024 ]; then
    lvextend -q -r -l +100%FREE "$ROOT_DEV" >/dev/null 2>&1 && ok "main partition grown to fill the disk" \
      || warn "could not grow the main partition"
  else ok "main partition already uses the whole disk"; fi
else ok "no change needed (main partition is not on LVM)"; fi
FREE_GB=$(df -BG --output=avail / | tail -1 | tr -dc 0-9)
[ "${FREE_GB:-0}" -ge 8 ] && ok "${FREE_GB} GB free inside the VM" \
  || warn "only ${FREE_GB} GB free inside the VM - about 6 GB is needed"

# ---- 2. the desktop and the browser --------------------------------------------
export DEBIAN_FRONTEND=noninteractive
step "Turning off automatic updates (so everyone starts from the same system)"
systemctl disable --now unattended-upgrades.service apt-daily.timer apt-daily-upgrade.timer >/dev/null 2>&1 || true
cat > /etc/apt/apt.conf.d/99-no-auto-updates <<'EOF'
APT::Periodic::Update-Package-Lists "0";
APT::Periodic::Unattended-Upgrade "0";
EOF
ok "apt updates are now manual"
dpkg --configure -a >/dev/null 2>&1 || true
step "Updating the package lists"
long apt-get update -qq || fail "apt-get update failed - check the VM's internet connection."
step "Installing the minimal Ubuntu desktop (often 15-30 minutes)"
long apt-get install -y -qq ubuntu-desktop-minimal || fail "desktop install failed - see $LOG, then run this script again."
ok "ubuntu-desktop-minimal"
# VirtualBox's display adapter cannot draw GNOME's mouse pointer, and the
# screen stays black after login. A software pointer fixes it.
grep -q '^MUTTER_DEBUG_DISABLE_HW_CURSORS=' /etc/environment || echo 'MUTTER_DEBUG_DISABLE_HW_CURSORS=1' >> /etc/environment
ok "software mouse pointer (needed for GNOME in VirtualBox)"
put() { install -d -m 755 "$(dirname "$2")"; cat > "$2"; chmod "$1" "$2"; }
put_b64() { install -d -m 755 "$(dirname "$2")"; base64 -d > "$2"; chmod "$1" "$2"; }
# Fonts go in before the Firefox snap: snapd sets up the font folders a snap
# can see when the snap is installed.
FD=/usr/local/share/fonts/custom
install -d -m 755 "$FD"
put_b64 644 "$FD/AtkinsonHyperlegible-Regular.ttf" <<'MINPROJ_EOF'
