command -v fc-cache >/dev/null 2>&1 && fc-cache -f >/dev/null 2>&1
if snap list firefox >/dev/null 2>&1; then
  snap disconnect firefox:desktop >/dev/null 2>&1; snap connect firefox:desktop >/dev/null 2>&1
fi
ok "page font installed in $FD"
if [ $TEST -eq 0 ]; then
  step "Installing Firefox (a snap, as Ubuntu ships it)"
  snap list firefox >/dev/null 2>&1 || long snap install firefox || fail "could not install the Firefox snap - check the internet connection and run again."
  ok "firefox snap"
  snap refresh --hold >/dev/null 2>&1 && ok "snap updates on hold" || warn "could not hold snap updates"
fi

# ---- 3. the inherited workstation: what a previous admin left behind --------------
step "Adding what the previous admin left behind"
echo "postfix postfix/main_mailer_type select Local only" | debconf-set-selections
echo "postfix postfix/mailname string old-workstation.local" | debconf-set-selections
long apt-get install -y -qq cups cups-browsed postfix python3-doc manpages-dev \
  && ok "printing (cups), a mail server (postfix), extra documentation" || warn "some extras did not install"
apt-mark manual cups cups-browsed postfix python3-doc manpages-dev >/dev/null 2>&1

# an older kernel, kept
if [ $TEST -eq 0 ]; then
  RUN=$(uname -r)
  OLD=$(apt-cache search --names-only '^linux-image-[0-9][0-9.]*-[0-9]+-generic$' 2>/dev/null \
        | cut -d' ' -f1 | sed 's/^linux-image-//' | sort -V | while read -r v; do
            [ "$(printf '%s\n%s\n' "$v" "$RUN" | sort -V | head -1)" = "$v" ] && [ "$v" != "$RUN" ] && echo "$v"; done | tail -1)
  if [ -n "$OLD" ]; then
    long apt-get install -y -qq "linux-image-$OLD" && apt-mark manual "linux-image-$OLD" >/dev/null \
      && ok "older kernel $OLD kept" || warn "could not install the older kernel $OLD"
  else
    warn "no older kernel in the archive yet - skipped"
  fi
fi

# an old account, an old monitoring service, a cron job and old logs
id oldadmin >/dev/null 2>&1 || useradd -m -s /bin/bash -c "Previous admin" oldadmin
usermod -L oldadmin
chmod 755 /home/oldadmin
install -d -o oldadmin -g oldadmin "/home/oldadmin/scripts"
cat > /home/oldadmin/NOTES.txt <<'EOF'
Cleanup list for this workstation (not finished)

- printing is not used here. purge cups and cups-browsed
- the old kernel can go. purge it with apt
- zz-legacy-intranet in autostart looks old. delete it
- snapd is only for old stuff. remove it
- snap list shows gnome-core26, mesa-2604, gtk-common-themes ...
  nobody installed those on purpose. remove them
- old-monitor writes the load average every minute and nobody reads it.
  disable it and delete /usr/local/sbin/old-monitor
- the old-backup cron job fills /var/backups. delete
  /etc/cron.d/old-backup and the old copies
- /var/log/old-app is logs from an app we removed. delete it
- delete files that no package owns (look in /usr/local)
- AppArmor slows the start. turn it off: add apparmor=0 to
  GRUB_CMDLINE_LINUX_DEFAULT in /etc/default/grub, then update-grub
- run apt autoremove now and then, it keeps the disk small
- oldadmin is locked and nobody uses it. remove the account and its home:
  sudo deluser --remove-home oldadmin
- the intranet page should not live in an old admin's home. move it
  somewhere better
EOF
chown oldadmin:oldadmin /home/oldadmin/NOTES.txt; chmod 644 /home/oldadmin/NOTES.txt
cat > /usr/local/sbin/old-monitor <<'EOF'
#!/bin/sh
# Writes the load average every minute. Nobody reads it.
while true; do cat /proc/loadavg > /var/log/old-monitor.log; sleep 60; done
EOF
chmod 755 /usr/local/sbin/old-monitor
cat > /etc/systemd/system/old-monitor.service <<'EOF'
[Unit]
Description=Old load monitor

[Service]
ExecStart=/usr/local/sbin/old-monitor

[Install]
WantedBy=multi-user.target
EOF
cat > /etc/cron.d/old-backup <<'EOF'
# Copies /etc every 30 minutes. Keeps 24 copies.
*/30 * * * * root tar -czf /var/backups/old-etc-$(date +\%H).tgz /etc 2>/dev/null
EOF
install -d /var/log/old-app
for i in 1 2 3 4 5 6 7 8; do
  [ -f "/var/log/old-app/app.log.$i" ] || head -c 2500000 /dev/urandom | base64 > "/var/log/old-app/app.log.$i"
done
ok "account oldadmin (locked) and its notes, old-monitor service, a cron job, old logs"

# ---- 4. the target: the intranet page, opened by Firefox at login -----------------
step "Setting up the intranet page"
SRC=/home/oldadmin/shared/intranet
install -d -m 755 /home/oldadmin/shared
install -d -o "$U" -g "$U" -m 755 "$SRC" "$UHOME/intranet"
grep -q " $UHOME/intranet " /etc/fstab || echo "$SRC $UHOME/intranet none bind 0 0" >> /etc/fstab
systemctl daemon-reload
mountpoint -q "$UHOME/intranet" || mount --bind "$SRC" "$UHOME/intranet"
W="$SRC"
put 644 "$W/index.html" <<'MINPROJ_EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Distro Minimisation Project — Functional Target Page</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <!-- Fixed status badge: always on screen regardless of scroll position, so both
       humans and the staff timing harness can read the JS state at a glance. -->
  <div id="js-badge" class="badge-fail">JS: FAILED</div>

  <header class="banner">
    <img src="img/banner.png" alt="COMP2812 Systems Software banner">
  </header>

  <main class="page">
    <section class="callout">
      <strong>Functional check.</strong> If you can see this page <em>styled</em> (colours,
      cards, spacing), Figure&nbsp;1 renders as an image, <em>and</em> the box at
      Figure&nbsp;2 reads <strong>&ldquo;JavaScript check: PASSED&rdquo;</strong> with the
      chart drawn below it, then your minimised system still has a working graphical
      browser, image stack, and JavaScript engine. That is the functional target. A
      text-mode browser &mdash; or a graphical browser without working JavaScript &mdash;
      will fail this check.
    </section>

    <h1>Systems Software: what a minimised system must still do</h1>

    <p>
      This page is deliberately self-contained &mdash; plain HTML and CSS with local images,
      no internet required. It exists so the assessment can confirm one thing: after you strip
      the system down, a real graphical browser can still open a page and display it in its
      original form, figures included.
    </p>

    <figure>
      <img src="img/os-stack.png" alt="Diagram of operating system layers from hardware up to applications">
      <figcaption>Figure 1. The layers you must keep working to display this page: hardware,
      the Linux kernel, system libraries and the graphical stack, and the applications on top.</figcaption>
    </figure>

    <p>
      Everything above the hardware is negotiable to a point &mdash; the skill in this project is
      deciding what is genuinely essential to keep this page rendering, and how
      small each remaining piece can be, without breaking the job.
    </p>

    <figure>
      <div id="js-status" class="js-fail">
        <strong>JavaScript check: FAILED.</strong> This browser did not run the page&rsquo;s
        JavaScript, so Figure&nbsp;2 cannot be drawn. The functional target requires a
        graphical browser with a working JavaScript engine.
      </div>
      <canvas id="size-chart" width="680" height="300" hidden
              aria-label="Bar chart of achieved minimised system sizes in megabytes"></canvas>
      <figcaption>Figure 2. Example sizes of minimised Linux systems (MB),
      drawn at load time by this page&rsquo;s JavaScript. Smaller is the goal &mdash; but only
      while this page still displays correctly.</figcaption>
    </figure>

    <h2>The rules that make this a real test</h2>
    <ul>
      <li>It must still work <strong>after a reboot</strong> &mdash; not just once.</li>
      <li>Nothing may be <strong>installed on demand</strong> when the page is opened.</li>
      <li>The browser must be <strong>restartable</strong>.</li>
    </ul>
  </main>

  <footer class="foot">
    COMP2812 / COMP9812 Systems Software &middot; Distro Minimisation Project &middot; functional target page
  </footer>

  <script>
    (function () {
      "use strict";
      // Figure 2 data: example sizes of minimised Linux systems (MB).
      var data = [
        { label: "A", mb: 214 },
        { label: "B", mb: 342 },
        { label: "C", mb: 505 },
        { label: "D", mb: 693 },
        { label: "E", mb: 918 },
        { label: "F", mb: 1460 },
        { label: "G", mb: 2130 },
        { label: "H", mb: 2900 }
      ];

      var canvas = document.getElementById("size-chart");
      var status = document.getElementById("js-status");
      if (!canvas || !canvas.getContext || !status) { return; }

      var ctx = canvas.getContext("2d");
      var W = canvas.width, H = canvas.height;
      var padL = 56, padR = 16, padT = 18, padB = 40;
      var plotW = W - padL - padR, plotH = H - padT - padB;
      var max = 3000; // MB axis ceiling

      // axes
      ctx.strokeStyle = "#8fa3bd";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, padT);
      ctx.lineTo(padL, padT + plotH);
      ctx.lineTo(padL + plotW, padT + plotH);
      ctx.stroke();

      // y gridlines + labels
      ctx.fillStyle = "#52627a";
      ctx.font = "12px system-ui, sans-serif";
      ctx.textAlign = "right";
      for (var g = 0; g <= max; g += 500) {
        var gy = padT + plotH - (g / max) * plotH;
        ctx.fillText(String(g), padL - 8, gy + 4);
        if (g > 0) {
          ctx.strokeStyle = "#e3eaf3";
          ctx.beginPath();
          ctx.moveTo(padL, gy);
          ctx.lineTo(padL + plotW, gy);
          ctx.stroke();
        }
      }

      // bars
      var slot = plotW / data.length;
      var barW = slot * 0.58;
      ctx.textAlign = "center";
      for (var i = 0; i < data.length; i++) {
        var h = (data[i].mb / max) * plotH;
        var x = padL + i * slot + (slot - barW) / 2;
        var y = padT + plotH - h;
        ctx.fillStyle = i === 0 ? "#1d7a46" : "#3568a8";
        ctx.fillRect(x, y, barW, h);
        ctx.fillStyle = "#1c2733";
        ctx.fillText(String(data[i].mb), x + barW / 2, y - 5);
        ctx.fillStyle = "#52627a";
        ctx.fillText("Team " + data[i].label, x + barW / 2, padT + plotH + 16);
      }
      ctx.fillStyle = "#52627a";
      ctx.fillText("Minimised size (MB) — lower is better", padL + plotW / 2, padT + plotH + 33);

      // flip the status box: JavaScript ran and the figure is drawn.
      canvas.hidden = false;
      status.className = "js-pass";
      status.innerHTML = "<strong>JavaScript check: PASSED.</strong> This figure was drawn " +
        "by the page’s JavaScript at load time.";
      var badge = document.getElementById("js-badge");
      if (badge) { badge.className = "badge-pass"; badge.textContent = "JS: PASSED"; }

      // the page font: is "Atkinson Hyperlegible" installed? (text width with and without it)
      function textWidth(family) {
        var s = document.createElement("span");
        s.style.cssText = "position:absolute;visibility:hidden;font-size:40px;font-family:" + family;
        s.textContent = "mmmmmmmmmmlli 0123456789";
        document.body.appendChild(s);
        var w = s.offsetWidth;
        document.body.removeChild(s);
        return w;
      }
      var fontOK = textWidth('"Atkinson Hyperlegible", monospace') !== textWidth("monospace") ||
                   textWidth('"Atkinson Hyperlegible", serif') !== textWidth("serif");
      if (!fontOK && badge) { badge.className = "badge-fail"; badge.textContent = "FONT: MISSING"; }
    })();
  </script>
</body>
</html>
MINPROJ_EOF
put 644 "$W/style.css" <<'MINPROJ_EOF'
/* Self-contained styles. The text font (Atkinson Hyperlegible) is installed on the system, not in this folder. */
* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Atkinson Hyperlegible", sans-serif;
  color: #1c2733;
  background: #eef2f7;
  line-height: 1.55;
}

.banner { margin: 0; }
.banner img { display: block; width: 100%; height: auto; }

.page {
  max-width: 820px;
  margin: 0 auto;
  padding: 28px 24px 40px;
  background: #ffffff;
  box-shadow: 0 2px 18px rgba(11, 31, 58, 0.10);
}

.callout {
  border-left: 5px solid #f2b134;
  background: #fff8e8;
  padding: 14px 16px;
  border-radius: 6px;
  margin-bottom: 26px;
}

h1 { font-size: 1.7rem; color: #0b1f3a; margin: 8px 0 14px; }
h2 { font-size: 1.25rem; color: #0b1f3a; margin: 28px 0 10px; }

p { margin: 0 0 16px; }

figure {
  margin: 24px 0;
  padding: 14px;
  background: #f6f9fc;
  border: 1px solid #dce5ef;
  border-radius: 10px;
  text-align: center;
}
figure img { max-width: 100%; height: auto; border-radius: 6px; }
figure canvas { max-width: 100%; height: auto; }

/* JavaScript functional check — default (no JS) is the red FAILED state;
   the page's script switches it to the green PASSED state. */
.js-fail, .js-pass {
  padding: 12px 14px;
  border-radius: 6px;
  margin-bottom: 12px;
  text-align: left;
}
.js-fail {
  border-left: 5px solid #c0392b;
  background: #fdecea;
  color: #7c261b;
}
.js-pass {
  border-left: 5px solid #1d7a46;
  background: #e9f7ef;
  color: #175c36;
}

/* Fixed corner badge — visible at any scroll position / screen size. The solid
   fill colours are what the staff timing harness detects on screenshots:
   pass = #1d7a46, fail = #c0392b. */
.badge-fail, .badge-pass {
  position: fixed;
  top: 10px;
  right: 10px;
  z-index: 1000;
  padding: 8px 14px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.95rem;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(11, 31, 58, 0.25);
}
.badge-fail { background: #c0392b; }
.badge-pass { background: #1d7a46; }
figcaption { margin-top: 10px; font-size: 0.92rem; color: #52627a; text-align: left; }

ul { margin: 0 0 8px; padding-left: 22px; }
li { margin-bottom: 6px; }

.foot {
  max-width: 820px;
  margin: 16px auto 40px;
  padding: 0 24px;
  font-size: 0.85rem;
  color: #7688a0;
  text-align: center;
}
MINPROJ_EOF
put_b64 644 "$W/img/banner.png" <<'MINPROJ_EOF'
