Type=Application
Name=legacy intranet
Exec=firefox --new-window file://$UHOME/intranet/index.html
X-GNOME-Autostart-enabled=true
EOF
chown "$U:$U" "$UHOME/.config/autostart/zz-legacy-intranet.desktop"
ok "Firefox opens the page when $U logs in"

# ---- 5. final-check -----------------------------------------------------------------
step "Installing final-check"
put 755 /usr/local/bin/final-check <<'MINPROJ_EOF'
#!/usr/bin/env bash
# =============================================================================
# final-check — Distro Minimisation Project (online version)
#
#   sudo final-check            check the target and print the results card
#   sudo final-check --export   also write the card and manifest to one file
#
# Your finished system must still run this script. It needs only bash and
# coreutils, and it must run as root (with sudo, or logged in as root).
# It reads the system. It writes only to /var/lib/minproj and, with
# --export, one file in the desktop user's home folder.
# =============================================================================

export LC_ALL=C
set -u
shopt -s nullglob globstar

VERSION="2027.4-online"
STATE=/var/lib/minproj
CLK=100   # kernel clock ticks per second (USER_HZ); 100 on Ubuntu x86_64 and arm64
# Graphical browsers that count for the target (process names, max 15 characters).
BROWSERS=" firefox firefox-bin chromium chromium-browse chrome epiphany falkon qutebrowser midori surf luakit vimb librewolf "

# band thresholds (from tools/bands.conf)
packages_size="50 60 75 90"
boot_boot="650 550 450 300"
display_boot="650 550 400 200"
display_size="85 90 95 100"
services_as="70 77 85 95"
# the provided page files and their sha256
EXPECTED=(
  "397a619c1e8bc0e9d74caa7df31623994014a3b74a53a350fbfcad9abbfd03b7 index.html"
  "cffc9e1f90e50d6decb41478e76e7528b5f98315429f18f3c6d7955fd28468a2 style.css"
  "ae2bdfba222e481661bb5a9b3f75e8cce7b068106b7857a772147e332f8ebe39 img/banner.png"
  "0f4a24c8eeb9a8420b96fc5d724dd7419674952b7ffdedbca6deaa38c1ea86cc img/os-stack.png"
  "f0d083b35a1d11f7cd9c2ed15e93c3d6edc6738f69ebe3cca265af074e2c7d25 img/size-chart.png"
)
K1="aG1mRFg2YWxwYkFtalEx"; K2="aVhHV3RIT01jVjdzbg=="

say()  { printf '%s\n' "$*"; }
key()  { printf '%s' "$K1$K2" | base64 -d; }
hash() { { key; printf '|%s' "$@"; } | sha256sum | cut -c1-64; }

[ "$(id -u)" -eq 0 ] || { say "Run it as root:  sudo final-check"; exit 1; }
[ -f "$STATE/USER" ] || { say "No project state in $STATE. Run the starter script first."; exit 1; }
DUSER=$(cat "$STATE/USER")
DUID=""; DGID=""; DHOME=""
while IFS=: read -r n _ uid gid _ home _; do
  [ "$n" = "$DUSER" ] && { DUID=$uid; DGID=$gid; DHOME=$home; }
done < /etc/passwd
ARCH=$(uname -m)
BOOT=$(cat /proc/sys/kernel/random/boot_id)

# ---------------------------------------------------------------------------
# 1. Is the target working in this boot?
# ---------------------------------------------------------------------------
PROBLEMS=()
PAGE="$DHOME/intranet"

# 1a. the browser: earliest graphical browser process in this boot
BTB=""   # boot-to-browser, in clock ticks since boot
for d in /proc/[0-9]*; do
  c=""; read -r c < "$d/comm" 2>/dev/null || continue
  case "$BROWSERS" in *" $c "*) ;; *) continue ;; esac
  s=""; read -r s < "$d/stat" 2>/dev/null || continue
  s=${s##*) }; read -r -a f <<< "$s"
  t=${f[19]:-}
  [[ "$t" =~ ^[0-9]+$ ]] || continue
  if [ -z "$BTB" ] || [ "$t" -lt "$BTB" ]; then BTB=$t; fi
done
if [ -z "$BTB" ]; then
  INST=""
  for b in firefox chromium chromium-browser google-chrome epiphany-browser falkon qutebrowser midori surf luakit vimb librewolf; do
    for bd in /snap/bin /usr/bin /usr/local/bin; do [ -x "$bd/$b" ] && { INST="$bd/$b"; break 2; }; done
  done
  if [ -z "$INST" ]; then
    PROBLEMS+=("No browser is installed. Which change removed it? Check /var/log/apt/history.log.")
  else
    PROBLEMS+=("A browser is installed ($INST) but is not running in this boot. What started it before your last change? Start it from a terminal and read any error.")
  fi
fi

# 1a2. split boot-to-browser into two parts, and leave out the time a person
#      waits at the login screen:
#      SCR   = start to login screen (systemd reached default.target)
#      LOGIN = the desktop user's first process in this boot (the login)
#      WAIT  = LOGIN - SCR, not counted
pstart() { local s; read -r s < "$1/stat" 2>/dev/null || return 1; s=${s##*) }; read -r -a f <<< "$s"; printf '%s' "${f[19]:-}"; }
BRAW=$BTB; SCR=""; LOGIN=""; WAIT=0; L2B=""
if [ -n "$BTB" ]; then
  us=$(systemctl show -p ActiveEnterTimestampMonotonic --value default.target 2>/dev/null)
  [[ "$us" =~ ^[0-9]+$ ]] && [ "$us" -gt 0 ] && SCR=$(( us * CLK / 1000000 ))
  while read -r u d; do
    [ "$u" = "$DUID" ] || continue
    t=$(pstart "$d") || continue
    [[ "$t" =~ ^[0-9]+$ ]] || continue
    if [ -z "$LOGIN" ] || [ "$t" -lt "$LOGIN" ]; then LOGIN=$t; fi
  done < <(stat -c '%u %n' /proc/[0-9]* 2>/dev/null)
  { [ -n "$LOGIN" ] && [ "$LOGIN" -le "$BRAW" ]; } || LOGIN=$BRAW
  [ -n "$SCR" ] || SCR=$LOGIN
  [ "$SCR" -lt "$LOGIN" ] && WAIT=$(( LOGIN - SCR ))
  BTB=$(( BRAW - WAIT ))
  L2B=$(( BRAW - LOGIN ))
  SCR=$(( BTB - L2B ))
fi

# 1b. the page files: present and unchanged
for e in "${EXPECTED[@]}"; do
  want=${e%% *}; rel=${e#* }
  if [ ! -f "$PAGE/$rel" ]; then
    PROBLEMS+=("The page file ~/intranet/$rel is missing. Where did the page files live before your last change?")
  elif [ "$(sha256sum "$PAGE/$rel" | cut -c1-64)" != "$want" ]; then
    PROBLEMS+=("The page file ~/intranet/$rel has changed. The provided files must not change.")
  fi
done

# 1c. the desktop user can read the page (owner, group or other permission)
if [ -f "$PAGE/index.html" ]; then
  read -r mode ouid ogid < <(stat -c '%a %u %g' "$PAGE/index.html")
  ingroup=0
  [ "$ogid" = "$DGID" ] && ingroup=1
  while IFS=: read -r _ _ gid members; do
    [ "$gid" = "$ogid" ] || continue
    case ",$members," in *",$DUSER,"*) ingroup=1 ;; esac
  done < /etc/group
  m=$((8#$mode)); readable=0
  if [ "$ouid" = "$DUID" ]; then (( m & 0400 )) && readable=1
  elif [ $ingroup -eq 1 ]; then (( m & 0040 )) && readable=1
  else (( m & 0004 )) && readable=1; fi
  [ $readable -eq 1 ] || PROBLEMS+=("User $DUSER is not allowed to read the page. Check who owns it, and which groups $DUSER is in.")
fi

# 1d. JavaScript is not turned off
for p in "$DHOME"/snap/firefox/common/.mozilla/firefox/*/prefs.js \
         "$DHOME"/snap/firefox/common/.mozilla/firefox/*/user.js \
         "$DHOME"/.mozilla/firefox/*/prefs.js "$DHOME"/.mozilla/firefox/*/user.js \
         /etc/firefox/policies/policies.json; do
  [ -r "$p" ] || continue
  while IFS= read -r line; do
    case "$line" in *javascript.enabled*false*) PROBLEMS+=("JavaScript is turned off in $p.") ;; esac
  done < "$p"
done

# 1e. the font the page uses (Atkinson Hyperlegible) is installed somewhere
nf=0
for fdir in /usr/share/fonts /usr/local/share/fonts "$DHOME/.local/share/fonts" "$DHOME/.fonts"; do
  for ff in "$fdir"/**/*; do
    case "${ff##*/}" in [Aa]tkinson*[Hh]yperlegible*.[ot]tf) nf=$((nf+1)); break 2 ;; esac
  done
done
[ $nf -gt 0 ] || PROBLEMS+=("The font the page uses is not installed. Which font does the page ask for, and where was it before your last change?")

TARGET=PASS; [ ${#PROBLEMS[@]} -eq 0 ] || TARGET=FAIL

# Baseline only: never record twice. Say so before the slow measuring.
if [ "${1:-}" = "--record-baseline" ] && [ -f "$STATE/baseline.txt" ]; then
  say "The baseline is already recorded. Your baseline ID is:"
  while IFS= read -r l; do case "$l" in baseline_code=*) say "${l#*=}" ;; esac; done < "$STATE/baseline.txt"
  exit 0
fi

# Baseline only: Firefox should open by itself at login. If it started late,
# the baseline boot-to-browser includes that wait. Ask before measuring.
NOTE=""
if [ "${1:-}" = "--record-baseline" ] && [ ! -f "$STATE/baseline.txt" ] && [ "$TARGET" = PASS ] \
   && [ -n "$L2B" ] && [ "$L2B" -gt $(( 60 * CLK )) ]; then
  say ""
  say "Note: Firefox started $(( L2B / CLK )) s after you logged in."
  say "  Your baseline boot-to-browser would include that wait."
  say "  Best: restart, log in, let Firefox open by itself, then run the starter again."
  read -r -p "Record the baseline anyway, with a note for staff? (y/n) " yn </dev/tty
  [ "$yn" = y ] || { say "Not recorded. Nothing was changed."; exit 1; }
  NOTE="Firefox started $(( L2B / CLK )) s after login"
fi

# ---------------------------------------------------------------------------
# 2. Measurements
# ---------------------------------------------------------------------------
say "Measuring disk use (this can take a few minutes)..."
MOUNTS=(/)
while read -r _ mp _; do
  case "$mp" in /boot|/boot/efi) MOUNTS+=("$mp") ;; esac
done < /proc/mounts
SIZE=0
DIRS=$(du -xb --max-depth=3 "${MOUNTS[@]}" 2>/dev/null)
while IFS=$'\t' read -r b p; do
  for mp in "${MOUNTS[@]}"; do [ "$p" = "$mp" ] && SIZE=$((SIZE+b)); done
done <<< "$DIRS"

# packages, from dpkg's own record (no dpkg command needed)
PKGS=(); pk=""; st=""
if [ -r /var/lib/dpkg/status ]; then
  while IFS= read -r line; do
    case "$line" in
      "Package: "*) pk=${line#Package: } ;;
      "Status: "*)  st=${line#Status: } ;;
      "") [ "$st" = "install ok installed" ] && PKGS+=("$pk"); pk=""; st="" ;;
    esac
  done < /var/lib/dpkg/status
  [ "$st" = "install ok installed" ] && PKGS+=("$pk")
fi
SNAPS=(); for s in /var/lib/snapd/snaps/*.snap; do s=${s##*/}; SNAPS+=("${s%.snap}"); done
UNITS=(); for u in /etc/systemd/system/*.wants/*; do UNITS+=("${u#/etc/systemd/system/}"); done

# attack-surface counts
lp=0
for nf in /proc/net/tcp /proc/net/tcp6; do
  [ -r "$nf" ] || continue
  while read -r _ _ _ stt _; do [ "$stt" = "0A" ] && lp=$((lp+1)); done < "$nf"
done
for nf in /proc/net/udp /proc/net/udp6; do
  [ -r "$nf" ] || continue
  while read -r _ _ _ stt _; do [ "$stt" = "07" ] && lp=$((lp+1)); done < "$nf"
done
la=0
while IFS=: read -r _ _ _ _ _ _ sh; do
  case "$sh" in */nologin|*/false|"") ;; *) la=$((la+1)) ;; esac
done < /etc/passwd
ep=0
while IFS=: read -r _ pw _; do [ -z "$pw" ] && ep=$((ep+1)); done < /etc/shadow
su=n/a
if command -v find >/dev/null 2>&1; then
  su=$(find / -xdev -type f -perm /6000 2>/dev/null | wc -l)
fi

# attack surface: enabled units + listening ports + login accounts + setuid/setgid files
if [[ "$su" =~ ^[0-9]+$ ]]; then ASNOW=$(( ${#UNITS[@]} + lp + la + su )); else ASNOW=""; fi

subname() {
  case "$1" in
    boot) echo "Boot and startup" ;; packages) echo "Packages and dependencies" ;;
    display) echo "Display and session" ;; services) echo "Services and security" ;; *) echo "$1" ;;
  esac
}

# /etc compared with the baseline
ETCNOW=$(for f in /etc/**; do [ -f "$f" ] && [ ! -L "$f" ] && printf '%s\t%s\n' "$f" "$(sha256sum "$f" | cut -c1-64)"; done | sort)

# ---------------------------------------------------------------------------
# 3. Record this run
# ---------------------------------------------------------------------------
printf '%s %s %s %s %s %s %s %s\n' "$(date '+%Y-%m-%dT%H:%M:%S')" "$BOOT" "$TARGET" "${BTB:-none}" "$SIZE" "${SCR:-none}" "${L2B:-none}" "$WAIT" >> "$STATE/runs.log"

# ---------------------------------------------------------------------------
# 4. Baseline mode (run once, by the starter script)
# ---------------------------------------------------------------------------
if [ "${1:-}" = "--record-baseline" ]; then
  TEAM="${2:-}"; SUB="${3:-}"
  [[ "$TEAM" =~ ^[a-z]{2,4}[0-9]{4}$ ]] || { say "Not a FAN: $TEAM (2-4 letters and 4 digits, for example stud0123)."; exit 1; }
  case "$SUB" in boot|packages|display|services) ;; *) say "Unknown subsystem: $SUB"; exit 1 ;; esac
  [ -n "$ASNOW" ] || { say "The find command is missing, so the attack surface cannot be measured."; exit 1; }
  if [ "$TARGET" != PASS ]; then
    say "The target is not working yet, so the baseline cannot be recorded:"
    for p in "${PROBLEMS[@]}"; do say "  - $p"; done
    exit 1
  fi
  RAND=$(head -c 3 /dev/urandom | od -An -tx1 | tr -d ' \n')
  CHK=$(hash B "$TEAM" "$RAND" "$SIZE" "$BTB" "$BOOT" "$ARCH" "${#PKGS[@]}" "${#UNITS[@]}" "$L2B" "$SUB" "$ASNOW" | cut -c1-6)
  CODE="B-$TEAM-$RAND-$CHK"
  {
    echo "team=$TEAM"; echo "baseline_code=$CODE"; echo "rand=$RAND"
    echo "size=$SIZE"; echo "btb=$BTB"; echo "boot=$BOOT"; echo "arch=$ARCH"
    echo "btb_to_login_screen=$SCR"; echo "btb_login_to_browser=$L2B"; echo "login_wait_not_counted=$WAIT"
    echo "packages=${#PKGS[@]}"; echo "units=${#UNITS[@]}"
    echo "subsystem=$SUB"; echo "attack=$ASNOW"
    echo "attack_parts=units ${#UNITS[@]} ports $lp accounts $la setuid $su"
    echo "date=$(date '+%Y-%m-%d %H:%M')"
    [ -n "$NOTE" ] && echo "note=$NOTE"
  } > "$STATE/baseline.txt"
  printf '%s\n' "$ETCNOW" > "$STATE/etc-baseline.txt"
  printf '%s\n' "${PKGS[@]}" | sort > "$STATE/packages-baseline.txt"
  say ""
  say "Baseline recorded:"
  say "  size              $SIZE bytes"
  say "  boot-to-browser   $((BTB/CLK)).$(( (BTB%CLK)*10/CLK )) s"
  say "    start to login screen  $((SCR/CLK)).$(( (SCR%CLK)*10/CLK )) s"
  say "    login to browser       $((L2B/CLK)).$(( (L2B%CLK)*10/CLK )) s"
  say "    (not counted: $((WAIT/CLK)).$(( (WAIT%CLK)*10/CLK )) s waiting at the login screen)"
  say "  packages          ${#PKGS[@]}"
  say "  enabled units     ${#UNITS[@]}"
  say "  attack surface    $ASNOW (units ${#UNITS[@]}, ports $lp, accounts $la, setuid/setgid $su)"
  say "  subsystem         $(subname "$SUB")"
  say ""
  say "  BASELINE ID:      $CODE"
  say ""
  [ -n "$NOTE" ] && say "  Note recorded for staff: $NOTE."
  say "Write down this baseline ID and put it in your write-up. You will see it again on your results card."
  exit 0
fi

[ -f "$STATE/baseline.txt" ] || { say "No baseline yet. Run the starter script again to record it."; exit 1; }
bget() { local l; while IFS= read -r l; do [ "${l%%=*}" = "$1" ] && { printf '%s' "${l#*=}"; return; }; done < "$STATE/baseline.txt"; }
TEAM=$(bget team); BCODE=$(bget baseline_code); BSIZE=$(bget size); BBTB=$(bget btb)
BBOOT=$(bget boot); BARCH=$(bget arch); BRAND=$(bget rand); BPK=$(bget packages); BUN=$(bget units)
BL2B=$(bget btb_login_to_browser); SUB=$(bget subsystem); BAS=$(bget attack)

# ---------------------------------------------------------------------------
# 5. Reboot check and boot-to-browser (average of the last two boots)
# ---------------------------------------------------------------------------
# Uses the last two boots with a run (not the baseline boot). For each boot,
# the latest run in that boot counts. PASS needs both boots to have passed.
declare -A RES=() TIX=()
ORDER=()
while read -r _ b r t _; do
  [ ${#b} -eq 36 ] || continue
  [ "$b" = "$BBOOT" ] && continue
  [ -n "${RES[$b]:-}" ] || ORDER+=("$b")
  RES[$b]=$r; TIX[$b]=$t
done < "$STATE/runs.log"
NO=${#ORDER[@]}; USE=("${ORDER[@]:$(( NO > 2 ? NO - 2 : 0 ))}")
NB=0; SUM=0; PASSBOOTS=""
for b in "${USE[@]}"; do
  if [ "${RES[$b]}" = PASS ] && [ "${TIX[$b]}" != none ]; then
    NB=$((NB+1)); SUM=$((SUM+TIX[$b])); PASSBOOTS="$PASSBOOTS${PASSBOOTS:+,}$b"
  fi
done
if [ "$NB" -gt 0 ]; then MED=$((SUM/NB)); else MED=""; fi
if [ "$TARGET" = PASS ] && [ "$NB" -ge 2 ]; then REBOOT=PASS; else REBOOT=FAIL; fi
if [ "$TARGET" = PASS ]; then RNOTE="target passed in $NB of the last 2 boots"; else RNOTE="the target is not working now"; fi

# ---------------------------------------------------------------------------
# 6. Bands, manifest, result ID
# ---------------------------------------------------------------------------
band_low() {  # value thresholds(HD DN CR P): lower is better
  local v=$1; set -- $2
  [ "$v" -le "$1" ] && { echo HD; return; }; [ "$v" -le "$2" ] && { echo DN; return; }
  [ "$v" -le "$3" ] && { echo CR; return; }; [ "$v" -le "$4" ] && { echo P; return; }; echo "below P"
}
band_high() { # value thresholds(HD DN CR P): higher is better
  local v=$1; set -- $2
  [ "$v" -ge "$1" ] && { echo HD; return; }; [ "$v" -ge "$2" ] && { echo DN; return; }
  [ "$v" -ge "$3" ] && { echo CR; return; }; [ "$v" -ge "$4" ] && { echo P; return; }; echo "below P"
}
RANKS="HD DN CR P"
lower() {     # the lower of two bands
  local a=$1 b=$2 r
  for r in $RANKS; do [ "$a" = "$r" ] && { echo "$b"; return; }; [ "$b" = "$r" ] && { echo "$a"; return; }; done
  echo "$a"
}
PCT10=$(( SIZE * 1000 / BSIZE ))          # size as % of baseline, x10
if [ -n "$MED" ] && [ "$MED" -gt 0 ]; then SPD=$(( BBTB * 100 / MED )); else SPD=0; fi   # speed-up x100
if [ -n "$ASNOW" ] && [ "${BAS:-0}" -gt 0 ]; then APCT10=$(( ASNOW * 1000 / BAS )); else APCT10=""; fi
NM="not marked"; SBAND=$NM; BBAND=$NM; ABAND=$NM
case "$SUB" in
  packages) SBAND=$(band_low $((PCT10/10)) "$packages_size"); MBAND=$SBAND ;;
  boot)     if [ "$SPD" -gt 0 ]; then BBAND=$(band_high "$SPD" "$boot_boot"); else BBAND="no data"; fi; MBAND=$BBAND ;;
  display)  SBAND=$(band_low $((PCT10/10)) "$display_size")
            if [ "$SPD" -gt 0 ]; then BBAND=$(band_high "$SPD" "$display_boot"); else BBAND="no data"; fi
            MBAND=$(lower "$SBAND" "$BBAND") ;;
  services) if [ -n "$APCT10" ]; then ABAND=$(band_low $((APCT10/10)) "$services_as"); else ABAND="no data (find is missing)"; fi; MBAND=$ABAND ;;
  *)        MBAND="no subsystem recorded" ;;
esac
if [ "$REBOOT" != PASS ]; then
  for v in SBAND BBAND ABAND; do [ "${!v}" = "$NM" ] || printf -v "$v" '%s' "none (no reboot check)"; done
  MBAND="none (no reboot check)"
fi

MANIFEST=$(
  echo "## packages (${#PKGS[@]}; baseline $BPK)"; printf '%s\n' "${PKGS[@]}" | sort
  echo "## snaps (${#SNAPS[@]})"; printf '%s\n' "${SNAPS[@]}" | sort
  echo "## enabled units (${#UNITS[@]}; baseline $BUN)"; printf '%s\n' "${UNITS[@]}" | sort
  echo "## attack surface"
  echo "enabled_units=${#UNITS[@]}"; echo "listening_ports=$lp"; echo "login_accounts=$la"; echo "empty_passwords=$ep"; echo "setuid_setgid_files=$su"
  echo "attack_surface=${ASNOW:-n/a} (baseline $BAS)"
  echo "## /etc compared with baseline (+ added, - removed, ~ changed)"
  join -t $'\t' -v1 <(printf '%s\n' "$ETCNOW") "$STATE/etc-baseline.txt" | while IFS=$'\t' read -r p _; do echo "+ $p"; done
  join -t $'\t' -v2 <(printf '%s\n' "$ETCNOW") "$STATE/etc-baseline.txt" | while IFS=$'\t' read -r p _; do echo "- $p"; done
  join -t $'\t' <(printf '%s\n' "$ETCNOW") "$STATE/etc-baseline.txt" | while IFS=$'\t' read -r p a b; do [ "$a" = "$b" ] || echo "~ $p"; done
  echo "## folders to depth 3, with sizes in bytes"; printf '%s\n' "$DIRS" | sort -k2
  echo "## 100 largest files, sizes in bytes"; n=0; while IFS=$'\t' read -r b p; do [ -f "$p" ] || continue; printf '%s\t%s\n' "$b" "$p"; n=$((n+1)); [ $n -ge 100 ] && break; done < <(du -axb "${MOUNTS[@]}" 2>/dev/null | sort -rn)
  echo "## boot IDs where the target passed"; printf '%s\n' "${PASSBOOTS//,/$'\n'}"
)
FP=$(printf '%s\n' "$MANIFEST" | sha256sum | cut -c1-64)
TCODE_RAW=$(hash R "$TEAM" "$BCODE" "$BSIZE" "$BBTB" "$BBOOT" "$BARCH" "$SIZE" "${MED:-0}" "$NB" "$PASSBOOTS" "$REBOOT" "$FP" "$VERSION" "$SUB" "$BAS" "${ASNOW:-}")
TCODE="R-$TEAM-${TCODE_RAW:0:4}-${TCODE_RAW:4:4}-${TCODE_RAW:8:4}"

secs() { [ -n "$1" ] && printf '%d.%d s' $(( $1/CLK )) $(( ($1%CLK)*10/CLK )) || printf 'n/a'; }
gib()  { printf '%d.%02d GiB' $(( $1/1073741824 )) $(( ($1%1073741824)*100/1073741824 )); }

CARD=$(
  echo "=================== RESULTS CARD ==================="
  echo "Distro Minimisation Project   $TEAM   $ARCH"
  echo "Subsystem        $(subname "$SUB")"
  echo "----------------------------------------------------"
  printf 'Size now         %-11s baseline %s\n' "$(gib "$SIZE")" "$(gib "$BSIZE")"
  printf '                 = %d.%d%% of baseline        band: %s\n' $((PCT10/10)) $((PCT10%10)) "$SBAND"
  printf 'Boot-to-browser  %-11s baseline %s\n' "$(secs "$MED")" "$(secs "$BBTB")"
  printf '                 = %d.%02dx faster             band: %s\n' $((SPD/100)) $((SPD%100)) "$BBAND"
  printf '  This boot:     start to login screen %s\n' "$(secs "$SCR")"
  printf '                 login to browser      %s\n' "$(secs "$L2B")"
  printf '                 (not counted: %s waiting at the login screen)\n' "$(secs "$WAIT")"
  printf 'Attack surface   %-11s baseline %s\n' "${ASNOW:-n/a}" "$BAS"
  if [ -n "$APCT10" ]; then
    printf '                 = %d.%d%% of baseline        band: %s\n' $((APCT10/10)) $((APCT10%10)) "$ABAND"
  else
    printf '                 (find is missing)          band: %s\n' "$ABAND"
  fi
  echo "Target now       $TARGET"
  echo "Reboot check     $REBOOT ($RNOTE)"
  echo "Baseline ID      $BCODE"
  [ -n "$BL2B" ] && [ "$BL2B" -gt $(( 60 * CLK )) ] && echo "Baseline note    Firefox started $(( BL2B / CLK )) s after login"
  echo "Your band        $MBAND"
  echo "Result ID        $TCODE"
  echo "===================================================="
)
say ""
say "$CARD"
if [ "$TARGET" = FAIL ]; then
  say "The target is not working:"
  for p in "${PROBLEMS[@]}"; do say "  - $p"; done
elif [ "$NB" -lt 2 ]; then
  say "Restart the computer, open the page again, and run final-check again."
fi
say "Bands are provisional. Staff confirm them with the verify tool."

# ---------------------------------------------------------------------------
# 7. Export
# ---------------------------------------------------------------------------
if [ "${1:-}" = "--export" ]; then
  OUT="$DHOME/final-check-export-$TEAM-$(date '+%Y%m%d-%H%M').txt"
  {
    echo "$CARD"
    echo "== CARD DATA =="
    echo "version=$VERSION"; echo "team=$TEAM"; echo "arch=$ARCH"
    echo "baseline_code=$BCODE"; echo "baseline_rand=$BRAND"; echo "baseline_size=$BSIZE"
    echo "baseline_btb=$BBTB"; echo "baseline_boot=$BBOOT"; echo "baseline_arch=$BARCH"
    echo "baseline_packages=$BPK"; echo "baseline_units=$BUN"; echo "baseline_login_to_browser=$BL2B"
    echo "size=$SIZE"; echo "btb_median=${MED:-0}"; echo "pass_boots=$NB"; echo "boot_ids=$PASSBOOTS"
    echo "subsystem=$SUB"; echo "baseline_attack=$BAS"; echo "attack=${ASNOW:-}"
    echo "reboot=$REBOOT"; echo "target=$TARGET"; echo "manifest_sha256=$FP"; echo "team_code=$TCODE"
    echo "== MANIFEST =="
    printf '%s\n' "$MANIFEST"
  } > "$OUT"
  chown "$DUID:$DGID" "$OUT" 2>/dev/null
  say ""
  say "Saved: $OUT"
  say "Put this file in your OneDrive folder, with your VM. Paste its contents into your submission PDF."
  if command -v fstrim >/dev/null 2>&1; then
    fstrim -a >/dev/null 2>&1 && say "Freed unused disk blocks (fstrim), so the VM export is smaller."
  fi
fi
[ "$REBOOT" = PASS ]
MINPROJ_EOF
echo "$U" > "$STATE/USER"
ok "/usr/local/bin/final-check"

if [ $HAVE_SYSTEMD -eq 1 ] && [ $TEST -eq 0 ]; then
  systemctl daemon-reload
  systemctl enable -q old-monitor.service cups.service postfix.service 2>/dev/null
  systemctl set-default -q graphical.target
  ok "services enabled; the VM starts to the desktop"
fi
long apt-get clean
echo installed > "$STATE/STAGE"

echo
echo "First run done ($WARNINGS warnings). Full log: $LOG"
echo "Next:"
echo "  1. Restart:  sudo reboot"
echo "  2. Log in as $U. Firefox opens the page (the first time can take a minute)."
echo "  3. Check that the page shows the green 'JS: PASSED' badge."
echo "  4. Open a terminal (Ctrl+Alt+T) and run this script again:"
echo "       sudo bash $0"
